def move_credentials_to_profiles(apps, schema_editor):
    SystemConfig = apps.get_model('myHomePage', 'SystemConfig')
    Profile = apps.get_model('myHomePage', 'Profile')
    values = {}
    for category in MOVED:
        row = SystemConfig.objects.filter(category=category).exclude(value='').order_by('-updated_at').first()
        if row and (row.value or '').strip():
            values[category] = row.value.strip()
    if values:
        # The settings were site-wide; every existing profile gets them (normally one).
        for profile in Profile.objects.all():
            changed = []
            for name, value in values.items():
                if not getattr(profile, name):
                    setattr(profile, name, value)
                    changed.append(name)
            if 'orcid_access_token' in changed:
                profile.orcid_authorized_at = timezone.now()
                changed.append('orcid_authorized_at')
            if changed:
                profile.save(update_fields=changed)
    SystemConfig.objects.filter(category__in=REMOVED).delete()


def move_credentials_back(apps, schema_editor):
    SystemConfig = apps.get_model('myHomePage', 'SystemConfig')
    Profile = apps.get_model('myHomePage', 'Profile')
    profile = Profile.objects.order_by('order', 'id').first()
    for category in MOVED:
        value = getattr(profile, category, '') if profile else ''
        if value and not SystemConfig.objects.filter(category=category).exists():
            SystemConfig.objects.create(category=category, value=value, description='')


